"""The shared-rewards audit (docs/party/items_audit.md, generated by tools/party/item_tool.py gen-inc):
no GAP row, and the generated tables agree with the document. The C++ side (party-items-test test_audit) checks
that the shipped tables really give every `shared` row a path."""
import re
import unittest
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
AUDIT = ROOT / "docs/party/items_audit.md"
INC = ROOT / "gpu/shim/party/party_items.inc"


class ItemAuditTest(unittest.TestCase):
    def setUp(self):
        self.md = AUDIT.read_text(encoding="utf-8")
        self.inc = INC.read_text(encoding="utf-8")

    def rows(self, verdict):
        return [int(m.group(1)) for m in re.finditer(r"^\| (\d+) \|.*\| %s \|" % verdict, self.md, re.M)]

    def test_no_gap(self):
        self.assertEqual(self.rows("GAP"), [], "a lot gives a key / unique item, weapon or rune and no path shares it")
        self.assertRegex(self.md, r"\| GAP \| 0 \|")

    def test_inc_matches_document(self):
        shared = [int(x) for x in re.findall(r"^ITEM_REQUIRE_SHARED\((\d+),", self.inc, re.M)]
        per = [int(x) for x in re.findall(r"^ITEM_PER_PLAYER\((\d+),", self.inc, re.M)]
        self.assertEqual(shared, self.rows("shared"))
        self.assertEqual(per, self.rows("per-player"))

    def test_owner_cases(self):
        shared = set(self.rows("shared"))
        self.assertIn(2605010, shared)  # Living String (NW-4ae26be)
        self.assertIn(2400510, shared)  # a treasure weapon
        self.assertIn(2420234, shared)  # a treasure Caryll rune
        self.assertIn(3401800, shared)  # Ludwig's rune
        self.assertIn(2410900, shared)  # the questline
        self.assertNotIn(2410140, shared)  # an ordinary corpse stays per player
        self.assertRegex(self.inc, r"ITEM_KILL_AWARD\(2605010, 26, 2600129, 12600029, 5913\)")


if __name__ == "__main__":
    unittest.main()
